class CourseFullException extends RuntimeException {
    CourseFullException(String message) { super(message); }
}

class Course {
    private final String code;
    private int availableSeats;

    Course(String code, int capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("Capacity musi byc > 0"); // niezmiennik
        this.code = code;
        this.availableSeats = capacity;
    }

    void takeSeat() {
        if (availableSeats <= 0) throw new CourseFullException("Brak miejsc na kursie " + code);
        availableSeats--;
    }

    String code() { return code; }
}

record EnrollRequestDto(String studentEmail, String courseCode) {} // DTO - Lesson07

class EnrollStudentUseCase {
    private final CoursesModuleApi coursesModule; // publiczne API INNEGO modulu - Lesson17
    private final EnrollmentRepository repository;
    private final EventBus eventBus;

    EnrollStudentUseCase(CoursesModuleApi coursesModule, EnrollmentRepository repository, EventBus eventBus) {
        this.coursesModule = coursesModule;
        this.repository = repository;
        this.eventBus = eventBus;
    }

    void enroll(EnrollRequestDto request) {
        // POZIOM 1: format - tanie, bez I/O, NAJPIERW
        if (!request.studentEmail().contains("@")) throw new ValidationException("Zly format email");

        // POZIOM 3: regula biznesowa - wymaga stanu INNEGO modulu, przez publiczne API
        coursesModule.reserveSeat(request.courseCode());

        // POZIOM 2: niezmiennik domenowy - w konstruktorze encji
        Enrollment enrollment = new Enrollment(request.studentEmail(), request.courseCode());
        repository.save(enrollment); // CALA metoda to 1 transakcja - Lesson13

        eventBus.publish(new EnrollmentCreated(request.studentEmail(), request.courseCode())); // Lesson18
    }
}

